{
  "triples": [
    {
      "subject": "Semantic Classification",
      "predicate": "addresses",
      "object": "Human Needs categorization",
      "object_type": "Concept",
      "source_sentence": "Our goal is to explore whether semantic classification of terms can improve Human Needs categorization of affective events."
    },
    {
      "subject": "Co-training",
      "predicate": "uses",
      "object": "Models",
      "object_type": "Model",
      "source_sentence": "which is a co-training model that iteratively trains two models with different views of the data:"
    },
    {
      "subject": "classifier",
      "predicate": "uses",
      "object": "Words",
      "object_type": "Other",
      "source_sentence": "(1) an event expression classifier that uses the words in an event expression as input"
    },
    {
      "subject": "classifier",
      "predicate": "uses",
      "object": "Sentence",
      "object_type": "Other",
      "source_sentence": "(2) an event con- text classifier that uses the sentence contexts that mention an event as input."
    },
    {
      "subject": "Logistic Regression",
      "predicate": "uses",
      "object": "embeddings",
      "object_type": "Other",
      "source_sentence": "The event expression classifier is a logistic regression model that takes the embedding of an event expression as input"
    },
    {
      "subject": "classifier",
      "predicate": "uses",
      "object": "Semantic Classification",
      "object_type": "Other",
      "source_sentence": "but in this paper we aim to improve the event expression classifier by incorporating semantic classification."
    },
    {
      "subject": "Semantic Features",
      "predicate": "uses",
      "object": "Words",
      "object_type": "Other",
      "source_sentence": "we extract two types of semantic features from the head words of its 4 components."
    },
    {
      "subject": "Features",
      "predicate": "uses",
      "object": "Semantic Classes",
      "object_type": "Other",
      "source_sentence": "we create 10 real-valued features representing the confidence scores produced by the classifier for each of the 10 semantic classes."
    },
    {
      "subject": "Features",
      "predicate": "uses",
      "object": "Semantic Classes",
      "object_type": "Other",
      "source_sentence": "In addition, we create 10 binary features (one per semantic class) indicating whether any of the head words belongs to each class, based on the classifier 's predicted labels."
    }
  ]
}

